# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: pydantic-ai capability that lets the agent read one web page it was given a URL for
#          (a link the user pasted, or a source URL in a docs/ page), via the model provider's
#          native web fetch. No web search: it only reads pages, it doesn't look for them.
# Usage: add web_capability to an Agent's capabilities (wired up in ds.ai.agent). For Smash
#        questions docs/ and the data tools come first (spec/pkgs/ds/ai/knowledge_base.md).
# ---------------------------------------------------------------------------
from __future__ import annotations

from pydantic_ai.capabilities import WebFetch

__all__ = ["MAX_FETCHES", "MAX_PAGE_TOKENS", "WEB_RULE", "web_capability"]

MAX_FETCHES = 3  # per run: bounds cost and slow runs
MAX_PAGE_TOKENS = 8_000  # of one page's text, so a long page doesn't flood the context window

# Always-on (in ds.ai.agent's instructions): a deferred capability's own text isn't seen until
# it loads, and the point is to steer the model before it reaches for the web.
WEB_RULE = """\
Web pages (web_fetch) are a last resort for Smash Ultimate questions: answer from docs (search_docs) and the
data tools (SmashDb, start.gg, SmashTube) first, and fetch a page only for what they don't cover, or when the
user gives a link to read. Label every fact from a page "from the web: <url>". If a page disagrees with docs,
keep the docs answer first and add a Discrepancy note. For questions that aren't about Smash, fetch as needed."""

# ds::external-source: checked 2026-11-17 pydantic-ai 2.68 pydantic_ai.capabilities.WebFetch
#   taken from it: native=True (the provider fetches; raises UserError on a model without
#   native fetch), max_uses, max_content_tokens, defer_loading, description. No local fallback
#   on purpose: a local fetch would bypass ds.util.http (.agents/instructions/pkgs.md)
web_capability = WebFetch(
    max_uses=MAX_FETCHES,
    max_content_tokens=MAX_PAGE_TOKENS,
    # deferred: the tool definition only enters context once a page needs reading
    defer_loading=True,
    description="Read one web page from a URL already in the conversation (a pasted link, a docs source URL).",
)
